import{_ as t,o as i,c as a,ag as s}from"./chunks/framework.CVaJrGn7.js";const u=JSON.parse('{"title":"@guideflow/devtools","description":"@guideflow/devtools — Browser DevTools extension for visual tour building and flow inspection. Manifest V3 Chrome extension with AI-assisted tour authoring.","frontmatter":{"description":"@guideflow/devtools — Browser DevTools extension for visual tour building and flow inspection. Manifest V3 Chrome extension with AI-assisted tour authoring.","keywords":"@guideflow/devtools, tour builder extension, visual tour builder, GuideFlow DevTools, Chrome extension tour","head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/packages/devtools"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/packages/devtools"}],["meta",{"property":"og:title","content":"@guideflow/devtools — GuideFlow.js"}],["meta",{"property":"og:description","content":"@guideflow/devtools — Browser DevTools extension for visual tour building and flow inspection. Manifest V3 Chrome extension with AI-assisted tour authoring."}],["meta",{"name":"twitter:title","content":"@guideflow/devtools — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"@guideflow/devtools — Browser DevTools extension for visual tour building and flow inspection. Manifest V3 Chrome extension with AI-assisted tour authoring."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Packages\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Devtools\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/devtools/\\"}]}"]]},"headers":[],"relativePath":"packages/devtools.md","filePath":"packages/devtools.md","lastUpdated":1786207781000}'),o={name:"packages/devtools.md"};function n(l,e,r,d,p,h){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="guideflow-devtools" tabindex="-1">@guideflow/devtools <a class="header-anchor" href="#guideflow-devtools" aria-label="Permalink to &quot;@guideflow/devtools&quot;">​</a></h1><p><strong>Browser DevTools extension for visual tour building and flow inspection.</strong></p><div class="warning custom-block"><p class="custom-block-title">Coming Soon</p><p>The DevTools extension is currently in development and not yet published to browser extension stores.</p></div><h2 id="features-planned" tabindex="-1">Features (Planned) <a class="header-anchor" href="#features-planned" aria-label="Permalink to &quot;Features (Planned)&quot;">​</a></h2><ul><li>Visual tour builder — create tours by clicking on elements</li><li>Flow inspector — view active tour state, step data, and context</li><li>Event log — monitor tour events in real-time</li><li>Export — generate flow definitions from visual recordings</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li>Manifest V3 Chrome extension</li><li>React-based panel UI</li><li>Content script injects into inspected pages</li><li>Background service worker manages state</li></ul><h2 id="letting-it-see-your-app" tabindex="-1">Letting it see your app <a class="header-anchor" href="#letting-it-see-your-app" aria-label="Permalink to &quot;Letting it see your app&quot;">​</a></h2><p>The panel finds a page through the <code>window.__guideflow</code> global, and <strong>the library does not set it unless you ask</strong>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> gf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createGuideFlow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  exposeGlobal: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">meta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DEV</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or process.env.NODE_ENV !== &#39;production&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>It is opt-in rather than automatic because the global hands <em>any</em> script on the page a driveable tour instance — an analytics tag, a chat widget or an ad script could start, skip or end a tour and read <code>gf.progress</code>. Gate it on a development build and the panel works while you are building, without shipping the handle to production.</p><p><code>destroy()</code> clears the global again, and only if it still points at that instance — so two opted-in instances on one page cannot have the second&#39;s teardown unregister the first.</p><p>Without it the panel says plainly that the page is not running GuideFlow. That message is almost always this setting, not a bug.</p><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Not on the Chrome Web Store yet</p><p>There is no store listing. Publishing one needs a Google developer account, a US$5 fee, a privacy policy and a manual review — none of which is a code change. The listing copy, the privacy policy and a step-by-step runbook are written and waiting in <a href="https://github.com/RealNerdZW/GuideFlow/tree/master/packages/devtools/store" target="_blank" rel="noreferrer"><code>packages/devtools/store/</code></a>.</p><p>Until then, install it from a release zip or build it yourself.</p></div><h3 id="from-a-release-zip" tabindex="-1">From a release zip <a class="header-anchor" href="#from-a-release-zip" aria-label="Permalink to &quot;From a release zip&quot;">​</a></h3><p>Download <code>guideflow-devtools-&lt;version&gt;.zip</code> from the <a href="https://github.com/RealNerdZW/GuideFlow/actions" target="_blank" rel="noreferrer">CI artifacts</a>, unzip it, then load the unzipped folder as below.</p><h3 id="from-source" tabindex="-1">From source <a class="header-anchor" href="#from-source" aria-label="Permalink to &quot;From source&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/devtools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Then in Chrome:</p><ol><li>Navigate to <code>chrome://extensions</code></li><li>Enable <strong>Developer mode</strong></li><li>Click <strong>Load unpacked</strong></li><li>Select <code>packages/devtools/dist</code></li></ol><p>The extension makes <strong>no network calls of any kind</strong> — a test fails the build if one appears — and stores everything in your own browser profile.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/RealNerdZW/GuideFlow/tree/master/packages/devtools" target="_blank" rel="noreferrer">Source</a></li></ul>`,24)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
